; CMS-03 harmonic oscillator, symplectic Euler, Q2.29, 1608 steps, generated by repsynth.gen.isb.gen_workloads 0.3.0 for bwm. Do not edit.
; assembled after gen/isb/targets/bwm/bwm.cpu.asm
#bank ram
start:
    ld r13, uart_addr(r0)
    ld r12, exit_addr(r0)
    li r5, 1
    li r10, 28
    shl r6, r5, r10        ; r6 = 2^28, rounding term of qmul
    li r7, 29              ; r7 = Q
    shl r2, r5, r7         ; w2 = ONE
    shl r1, r5, r7         ; x = ONE
    li r3, 0               ; v = 0
    li r4, 1608
    li r8, 8
loop:
    beq r4, r0, done
    mul r10, r2, r1        ; v -= qmul(w2, x) >> 8
    add r10, r10, r6
    shr r10, r10, r7
    shr r10, r10, r8
    sub r3, r3, r10
    shr r10, r3, r8        ; x += v >> 8
    add r1, r1, r10
    sub r4, r4, r5
    jal r0, loop
done:
    li r9, msg_x
    jal r15, print
    add r9, r1, r0
    jal r15, hex32
    li r9, msg_v
    jal r15, print
    add r9, r3, r0
    jal r15, hex32
    li r9, msg_nl
    jal r15, print
    li r10, 0x5555
    sw r10, 0(r12)
hang:
    jal r0, hang
msg_x:
    #d8 0x6f, 0x73, 0x63, 0x69, 0x6c, 0x6c, 0x61, 0x74, 0x6f, 0x72, 0x20, 0x78, 0x3d, 0x00
msg_v:
    #d8 0x20, 0x76, 0x3d, 0x00
msg_nl:
    #d8 0x0a, 0x00
    #align 32
; print the zero-terminated string at r9; uses r10, r11; returns through r15
print:
    lb r10, 0(r9)
    beq r10, r0, print_end
    sb r10, 0(r13)
    add r9, r9, r5
    jal r0, print
print_end:
    jalr r0, 0(r15)
; print r9 as 8 hexadecimal digits of its low 32 bits (two's complement); uses r10, r11, r14; returns through r15
hex32:
    bge r9, r0, hex_pos
    li r10, 32
    shl r10, r5, r10
    add r9, r9, r10
hex_pos:
    li r14, 28
hex_loop:
    shr r10, r9, r14       ; x >> 4i
    li r11, 4
    add r11, r14, r11
    shr r11, r9, r11       ; x >> 4(i+1)
    li r8, 4
    shl r11, r11, r8
    sub r10, r10, r11      ; nibble
    li r11, 10
    blt r10, r11, hex_digit
    li r11, 87             ; 'a' - 10
    jal r0, hex_out
hex_digit:
    li r11, 48             ; '0'
hex_out:
    add r10, r10, r11
    sb r10, 0(r13)
    beq r14, r0, hex_end
    li r11, 4
    sub r14, r14, r11
    jal r0, hex_loop
hex_end:
    jalr r0, 0(r15)
    #align 64
uart_addr:
    #d64 $le(0x0000000010000000)
exit_addr:
    #d64 $le(0x0000000010100000)
